package ipc

import (
	"bytes"
	_ "embed"
	"encoding/hex"
	"encoding/json"
	"fmt"
)

// EmbeddedVectors is a copy of the Python repository's tests/test_vectors.json (generated by tests/make_vectors.py),
// so a built binary can check itself against the Python side's expectations in place (--self-test).
//
//go:embed testdata/test_vectors.json
var EmbeddedVectors []byte

// Vectors is the structure of test_vectors.json.
type Vectors struct {
	About      string         `json:"about"`
	Constants  map[string]any `json:"constants"`
	Identities struct {
		SenderID    string `json:"sender_id"`
		SenderToken string `json:"sender_token"`
		RemoteID    string `json:"remote_id"`
		KeyHex      string `json:"key_hex"`
		NonceHex    string `json:"nonce_hex"`
	} `json:"identities"`
	Frames     map[string]FrameVector `json:"frames"`
	LogChannel struct {
		JSONLine           string              `json:"json_line"`
		PlainLines         []map[string]string `json:"plain_lines"`
		LogBatchPayload    string              `json:"log_batch_payload"`
		SetLogLevelRequest string              `json:"set_log_level_request"`
		SetLogLevelReply   string              `json:"set_log_level_reply"`
		PingReplyExample   string              `json:"ping_reply_example"`
		RegisterPeerReply  string              `json:"register_peer_reply"`
	} `json:"log_channel"`
}

// FrameVector is one byte-exact frame.
type FrameVector struct {
	HeaderHex        string  `json:"header_hex"`
	FrameHex         string  `json:"frame_hex"`
	PayloadUTF8      string  `json:"payload_utf8"`
	MethodName       string  `json:"method_name"`
	RequestID        uint32  `json:"request_id"`
	ResponseExpected bool    `json:"response_expected"`
	KeepAlive        bool    `json:"keep_alive"`
	Compressed       bool    `json:"compressed"`
	Encrypted        bool    `json:"encrypted"`
	RemoteID         *string `json:"remote_id"`
	HeaderVersion    uint16  `json:"header_version"`
	AESGCM           bool    `json:"aes_gcm"`
}

// ParseVectors reads a test_vectors.json.
func ParseVectors(data []byte) (*Vectors, error) {
	var v Vectors
	if err := json.Unmarshal(data, &v); err != nil {
		return nil, fmt.Errorf("test vectors: %w", err)
	}
	return &v, nil
}

// CheckConstants compares the file's constants with this implementation's.
func (v *Vectors) CheckConstants() []string {
	ours := map[string]float64{"header_length_v1": HeaderLengthV1, "header_length_v2": HeaderLengthV2,
		"version_word_bytes": VersionWordBytes, "bit_response_expected": BitResponseExpected, "bit_compressed": BitCompressed,
		"bit_encrypted": BitEncrypted, "bit_keep_alive": BitKeepAlive, "bit_aes_gcm": BitAESGCM,
		"request_id_max_v1": RequestIDMaxV1, "request_id_max_v2": RequestIDMaxV2, "nonce_bytes": NonceBytes,
		"tag_bytes": TagBytes, "key_bytes": KeyBytes}
	var failures []string
	for name, want := range ours {
		got, ok := v.Constants[name].(float64)
		if !ok || got != want {
			failures = append(failures, fmt.Sprintf("constant %s: vectors say %v, implementation has %v", name, v.Constants[name], want))
		}
	}
	return failures
}

// CheckFrame unpacks and re-packs one frame vector and returns what disagreed (nothing for a match). Headers are
// compared byte for byte; payloads are reversed through decryption and decompression and, where the construct is
// deterministic (the fixed nonce), re-sealed to the same bytes. A compressed payload is checked by decompression,
// since zlib output is not identical across implementations.
func (v *Vectors) CheckFrame(name string, f FrameVector) []string {
	var failures []string
	fail := func(format string, args ...any) { failures = append(failures, name+": "+fmt.Sprintf(format, args...)) }
	headerBytes, err := hex.DecodeString(f.HeaderHex)
	if err != nil {
		return []string{name + ": header_hex: " + err.Error()}
	}
	frameBytes, err := hex.DecodeString(f.FrameHex)
	if err != nil {
		return []string{name + ": frame_hex: " + err.Error()}
	}
	sender := MustUUID(v.Identities.SenderID)
	token := MustUUID(v.Identities.SenderToken)
	key, _ := hex.DecodeString(v.Identities.KeyHex)
	nonce, _ := hex.DecodeString(v.Identities.NonceHex)
	var remote UUID
	if f.RemoteID != nil {
		remote = MustUUID(*f.RemoteID)
	}
	// 1. unpack the header and compare every field
	h, err := Unpack(headerBytes)
	if err != nil {
		return []string{name + ": unpack: " + err.Error()}
	}
	want := Header{Version: f.HeaderVersion, DataLength: uint64(len(frameBytes) - len(headerBytes)), MethodName: f.MethodName,
		RequestID: f.RequestID, SenderID: sender, SenderToken: token, ResponseExpected: f.ResponseExpected,
		Compressed: f.Compressed, Encrypted: f.Encrypted, KeepAlive: f.KeepAlive, AESGCM: f.AESGCM, RemoteID: remote}
	if h != want {
		fail("unpacked header %+v, expected %+v", h, want)
	}
	// 2. pack it again
	packed, err := h.Pack()
	if err != nil {
		fail("pack: %v", err)
	} else if !bytes.Equal(packed, headerBytes) {
		fail("packed header %x, expected %x", packed, headerBytes)
	}
	// 3. read the frame as a receiver would
	reader := bytes.NewReader(frameBytes)
	raw, h2, payload, err := readFrame(reader)
	if err != nil {
		return append(failures, name+": readFrame: "+err.Error())
	}
	if !bytes.Equal(raw, headerBytes) || h2 != h {
		fail("frame reader saw a different header")
	}
	if reader.Len() != 0 {
		fail("%d bytes left after the frame", reader.Len())
	}
	// 4. reverse the transforms
	body := payload
	if f.Encrypted {
		plain, err := Open(key, raw, body, f.AESGCM)
		if err != nil {
			return append(failures, name+": decrypt: "+err.Error())
		}
		resealed, err := SealWithNonce(key, nonce, raw, plain, f.AESGCM)
		if err != nil {
			fail("seal: %v", err)
		} else if !bytes.Equal(resealed, body) {
			fail("re-sealed payload differs from the vector")
		}
		if _, err := Open(key, append([]byte{}, raw[:len(raw)-1]...), body, f.AESGCM); err == nil {
			fail("decryption under an altered header did not fail")
		}
		body = plain
	}
	if f.Compressed {
		plain, err := Decompress(body)
		if err != nil {
			return append(failures, name+": decompress: "+err.Error())
		}
		ours, err := Compress(plain)
		if err != nil {
			fail("compress: %v", err)
		} else if back, err := Decompress(ours); err != nil || !bytes.Equal(back, plain) {
			fail("our compression does not round-trip")
		}
		body = plain
	}
	if string(body) != f.PayloadUTF8 {
		fail("payload %q, expected %q", string(body), f.PayloadUTF8)
	}
	// 5. build the frame from the fields alone, where the bytes are determined
	if !f.Compressed {
		plain := []byte(f.PayloadUTF8)
		h3 := want
		var built []byte
		if f.Encrypted {
			h3.DataLength = uint64(len(plain) + NonceBytes + TagBytes)
			hb, err := h3.Pack()
			if err == nil {
				var sealed []byte
				sealed, err = SealWithNonce(key, nonce, hb, plain, f.AESGCM)
				built = append(hb, sealed...)
			}
			if err != nil {
				fail("build: %v", err)
			}
		} else {
			h3.DataLength = uint64(len(plain))
			hb, err := h3.Pack()
			if err != nil {
				fail("build: %v", err)
			}
			built = append(hb, plain...)
		}
		if built != nil && !bytes.Equal(built, frameBytes) {
			fail("frame built from the fields %x, expected %x", built, frameBytes)
		}
	}
	return failures
}

// CheckFrames checks every frame vector; the map lists failures by vector name (empty for all good).
func (v *Vectors) CheckFrames() (checked int, failures []string) {
	for name, f := range v.Frames {
		checked++
		failures = append(failures, v.CheckFrame(name, f)...)
	}
	return checked, failures
}
